        if k in rb and ra[k]!=rb[k]:
            diffcols |= {cols[i] for i in range(len(cols)) if ra[k][i]!=rb[k][i]}
    print(t, 'differing columns:', sorted(diffcols), 'keys only one side:', len(set(ra)^set(rb)))
